const svgPt=(svg,ev)=>{const r=svg.getBoundingClientRect();const vb=svg.viewBox.baseVal;return [vb.x+(ev.clientX-r.left)/r.width*vb.width,vb.y+(ev.clientY-r.top)/r.height*vb.height];};
