G(6,()=>CH('Что такое Красная книга?','Список редких и исчезающих видов растений и животных, которые нужно охранять',['Атлас природных зон','Учебник по почвоведению','Список самых больших животных'],{short:'Красная книга — редкие виды.',explain:'<b>Красная книга</b> — список видов под угрозой исчезновения. Красный — цвет тревоги. Амурский тигр — в Красной книге.',explain2:'«Красный свет» — внимание, опасность.'}),{rule:true});
