/* ---------------- widgets ---------------- */
function onTheory(root){
 const z=root.querySelector('#w-zones');
 if(z){z.innerHTML=`<b>🧭 Путешествие от экватора к полюсу (вдоль 30° в. д.)</b>${SL('zL','Широта:',0,89,1,55)}<div id="zP" class="fig"></div><div id="zT" style="line-height:1.6;min-height:6em"></div>`;
  const g=id=>z.querySelector('#'+id);const u=()=>{const l=+g('zL').value;g('zLo').textContent=l+'° с. ш.';const Z=zoneAtLat(l);g('zP').innerHTML=figZones({lat:l,hl:Z[0]});
   g('zT').innerHTML=`<span class="out">${Z[0]}</span><br><b>Климат:</b> ${Z[5]}<br><b>Растения:</b> ${Z[6]}<br><b>Животные:</b> ${Z[7]}<br><b>Почвы:</b> ${Z[8]} · <b>Где:</b> ${Z[9]}`;};
  g('zL').oninput=u;u();}
 const b=root.querySelector('#w-belts');
 if(b){b.innerHTML=`<b>⛰ Поднимаемся в горы</b>${SL('bH','Высота:',0,3990,10,1200)}<div id="bP" class="fig"></div><div id="bT" style="text-align:center;line-height:1.6"></div>`;
  const g=id=>b.querySelector('#'+id);const u=()=>{const h=+g('bH').value;g('bHo').textContent=N(h)+' м';const B=BELTS.find(x=>h>=x[1]&&h<x[2]);g('bP').innerHTML=figBelts(h);g('bT').innerHTML=`Пояс: <span class="out">${B[0]}</span> · температура примерно на ${N(rnd(6*h/1000,1))} °C ниже, чем у подножия`;};
  g('bH').oninput=u;u();}
 const c=root.querySelector('#w-cyc');
 if(c){c.innerHTML=`<b>♻ Круговорот веществ: нажимай «Дальше»</b>${BTNS([['cN','Дальше ▶']])}<div id="cP" class="fig"></div><div id="cT" style="text-align:center;line-height:1.6;min-height:3em"></div>`;
  let st=0;const g=id=>c.querySelector('#'+id);const u=()=>{g('cP').innerHTML=figCycleB(st);g('cT').innerHTML=`<b>${CYCLE[st][0]}</b> — ${CYCLE[st][1]}`;};g('cN').onclick=()=>{st=(st+1)%5;u();};u();}
}

